import { z } from 'zod'
import { parseGridData } from './data-issues.ts'
import { municipalityLoadGroups, priceAreas } from './grid-ids.ts'

// Normalised daily load profiles per price area and Elhub municipality group, generated by the
// model build from Elhub's hourly price-area consumption. A value is the mean demand of the area
// and group at that local hour over the season's days of one day type, divided by the demand of
// the same area and group at the model's reference hour.

const factor = z.number().finite().nonnegative()
const day = z.array(factor).length(24)
const groups = z.object(Object.fromEntries(municipalityLoadGroups.map(group => [group, day])) as Record<typeof municipalityLoadGroups[number], typeof day>).strict()
const areas = z.object(Object.fromEntries(priceAreas.map(area => [area, groups])) as Record<typeof priceAreas[number], typeof groups>).strict()
const season = z.object({
  week: z.object({ startDate: z.string().regex(/^\d{4}-\d{2}-\d{2}$/), endDate: z.string().regex(/^\d{4}-\d{2}-\d{2}$/) }).strict(),
  weekday: areas,
  weekend: areas,
}).strict()

export const gridLoadProfilesSchema = z.object({
  schemaVersion: z.literal(1),
  id: z.string().regex(/^electric-grid(?:\.[a-z0-9]+(?:-[a-z0-9]+)*)+$/),
  modelId: z.string().min(1),
  timeZone: z.literal('Europe/Oslo'),
  referenceHour: z.iso.datetime({ offset: true }),
  normalisation: z.string().min(1),
  groupComposition: z.object(Object.fromEntries(municipalityLoadGroups.map(group => [group, z.array(z.string().min(1)).min(1)])) as Record<typeof municipalityLoadGroups[number], z.ZodArray<z.ZodString>>).strict(),
  siteLoads: z.string().min(1),
  sources: z.array(z.object({ sourceId: z.string().min(1), url: z.url(), retrievedAt: z.iso.datetime({ offset: true }), sha256: z.string().regex(/^[0-9a-f]{64}$/), licence: z.string().min(1) }).strict()).min(1),
  seasons: z.object({ winter: season, summer: season }).strict(),
}).strict()
export type GridLoadProfiles = z.infer<typeof gridLoadProfilesSchema>

export const validateGridLoadProfiles = (json: unknown, source: string): GridLoadProfiles =>
  parseGridData(gridLoadProfilesSchema, json, source, 'Grid Load Profiles')
